"""Generate the markdown docs from the eval/quality JSON files (numbers are never typed by hand)."""
import json, csv, pathlib
ROOT = pathlib.Path(__file__).resolve().parent.parent; J = lambda p: json.load(open(ROOT / p, encoding="utf-8"))
mb, ma = J("quality/metrics_baseline.json"), J("quality/metrics_after.json"); T = J("quality/thresholds.json"); E = J("eval/dedup_eval.json"); EJ = J("eval/dedup_eval_judge.json"); AP = J("eval/dedup_apply.json")
AG = J("eval/pairs_agreement.json"); CMP = J("eval/rag_comparison.json"); PR = J("eval/probe_dups.json"); DI = J("eval/defect_injection.json"); AD = J("eval/alternatives_demo.json")
def f(x): return f"{x:.4g}" if isinstance(x, float) else str(x)
# ---------------- profile ----------------
L = ["# Quality profile of the knowledge store (baseline = lab-11 hybrid store)", "", f"Snapshot: `store/` — {mb['info']['n_chunks']} chunks, graph (370 nodes / 757 relationships), 4 fixture notes. Metrics: `quality/profile.py`; thresholds: `quality/thresholds.json`.", "",
     "| id | dimension | metric | threshold | severity | baseline | verdict |", "|---|---|---|---|---|---|---|"]
for k, v in mb["metrics"].items(): L.append(f"| {k[:3]} | {v['dimension']} | {T[k]['desc']} | {v['op']} {v['threshold']} | {v['severity']} | {f(v['value'])} | {'ok' if v['ok'] else '**FAIL**'} |")
L += ["", "Severity: *blocking* failures fail the CI gate; *warning* failures are reported and tracked in the backlog (M06, M14).", "", "## Top-3 priorities by impact on RAG answers", "",
      f"1. **Conflicting statements (M03 = {mb['metrics']['M03_open_conflicts']['value']:.0f}, M04 = {mb['metrics']['M04_active_logical_violations']['value']:.0f}).** The model sees two values for the same fact (QD/FS/SOR thresholds, Java version) or a graph edge that breaks a rule; the answer is wrong, arbitrary or needlessly hedged. Impact is on correctness, so it is first.",
      f"2. **Near-duplicate chunks (M08 = {mb['metrics']['M08_near_duplicate_share']['value']:.2%}).** Duplicates fill top-k with the same text (retrieval probe: {PR['redundant_slots_before']} of {PR['total_slots']} top-5 slots redundant) and waste prompt tokens; on the 34 gold questions they do not occur in the contexts (see quality/after_report.md).",
      f"3. **Metadata and boundary defects in chunks (M06 = {mb['metrics']['M06_expert_sample_accuracy']['value']:.2f}, M01/M02 = {mb['metrics']['M01_completeness']['value']:.4f}).** Wrong document titles (4 documents), empty section names (3 chunks), chunks cut mid-sentence. They hurt citation quality and user trust; effect on automatic metrics is small.", ""]
open(ROOT / "quality/profile_baseline.md", "w", encoding="utf-8").write("\n".join(L))
# ---------------- dedup card ----------------
bf = E["by_feature"]
L = ["# Entity resolution (de-duplication) of chunks — method card", "",
     f"**Gold set.** {E['n']} pairs (stratified by score band) + 10 blocking-recall probes; two blind LLM annotators (labels DUP / RELATED / DISTINCT), binary agreement {AG['binary_agreement']}, Cohen's kappa {AG['binary_kappa']} (3-class {AG['three_class_kappa']}); {len(AG['disagreements'])} disagreement adjudicated by the assistant. Duplicates: {E['dup_dev']} dev / {E['dup_test']} test. Split: dev {E['n_dev']} / test {E['n_test']} (stratified by label, seed 14).",
     f"**Blocking.** Inverted index on word 5-shingles, pair if >= 2 shared: {E['blocking']['candidates']} candidate pairs out of {E['blocking']['all_pairs']} ({1 - E['blocking']['candidates'] / E['blocking']['all_pairs']:.1%} reduction). Probes (highest-embedding-similarity pairs not produced by blocking): {E['blocking']['probes_dup']} of {E['blocking']['probes']} are duplicates, i.e. no blocking miss was found.",
     "**Comparison types.** string (rapidfuzz token_set_ratio, ratio), sparse (TF-IDF cosine), dense (bge embedding cosine), attributes (same doc, section tail, length ratio, sensitivity). Score = .35 tfidf + .25 emb + .25 fuzz + .15 ratio, x0.85 if length ratio < 0.5.",
     f"**Threshold** tuned on dev: centre of the F1 plateau = **{E['threshold']}** (plateau {bf['score']['plateau'][0]}–{bf['score']['plateau'][1]}). Test (n={E['n_test']}, {E['dup_test']} duplicates): P = {bf['score']['test']['precision']}, R = {bf['score']['test']['recall']}, F1 = {bf['score']['test']['f1']}; bootstrap 95% CI P {E['test_ci95']['precision']}, R {E['test_ci95']['recall']} — wide, because there are only {E['dup_test']} positives. 5-fold CV over all pairs: P {E['cv5']['precision']}, R {E['cv5']['recall']}.",
     "", "| feature (threshold tuned on dev) | test P | test R | test F1 |", "|---|---|---|---|"]
for k, v in bf.items(): L.append(f"| {k} ({v['threshold']}) | {v['test']['precision']} | {v['test']['recall']} | {v['test']['f1']} |")
L += ["", "The combined score is **not better** than the best single feature on this small test set; it is kept because it is more stable in the CV and uses all comparison types.", "",
      f"**Errors at the score threshold:** " + "; ".join(f"{e['pair_id']} {e['kind']} (score {e['score']}, gold {e['gold']}, {e['split']})" for e in E["errors"]) + ".",
      f"**Borderline zone** (|score − th| <= {E['borderline_band']}): all candidate pairs of the store that fall into it and are not identical after normalisation ({EJ['judge_vs_gold']['judge_pairs']} pairs) were judged by a third LLM call that returned a label and an explanation ({EJ['judge_vs_gold']['judge_dup']} DUP / {EJ['judge_vs_gold']['judge_related']} RELATED). The judge agrees with the gold labels on {EJ['judge_vs_gold']['agree_binary']} of {EJ['judge_vs_gold']['in_gold']} judged pairs that are in the gold set (the judge was blind to the gold; annotators and judge are the same model family, so this is not independent evidence).",
      f"**Full rule on the gold set** (identical text → DUP; score >= th + band → DUP; borderline → judge; different sensitivity → never): dev P/R = {EJ['rule_evaluation']['dev']['with_judge']['precision']}/{EJ['rule_evaluation']['dev']['with_judge']['recall']}, test P/R = {EJ['rule_evaluation']['test']['with_judge']['precision']}/{EJ['rule_evaluation']['test']['with_judge']['recall']}; without the judge test R = {EJ['rule_evaluation']['test']['rule_without_judge']['recall']}.",
      f"**Merge.** {AP['merge_pairs']} pairs → {AP['clusters']} clusters, {AP['absorbed']} chunks absorbed ({AP['chunks_before']} → {AP['chunks_after']}); rule split {AP['by_rule']}. Canonical choice: public > internal > restricted, then longest, then smallest id. The canonical chunk keeps the full records of absorbed chunks in `merged_from` (doc, offsets, text, metadata); `quality/merge_log.jsonl` records cluster, rule and minimal pair score. **Unmerge** (`dedup.unmerge`) restores the exact original records: one cluster — {AP['unmerge_one_cluster']}, all clusters — {AP['unmerge_all_restores_original']} (tested, Q12).",
      "**Caveat.** Most merged clusters are boilerplate shared by nf-core/sarek and nf-core/raredisease pages; after the merge a sarek question is answered from the canonical raredisease chunk (provenance of the sarek span stays in `merged_from`). If a pipeline-specific answer is required, run `unmerge` for that cluster.", ""]
open(ROOT / "docs/dedup_card.md", "w", encoding="utf-8").write("\n".join(L))
# ---------------- conflicts ----------------
dec = list(csv.DictReader(open(ROOT / "quality/decisions.csv", encoding="utf-8")))
L = ["# Conflicts: detection, resolution and decision log", "", "Detection: `quality/conflicts.py` (rules over graph thresholds, fixture notes, corpus text, graph rules). Register of alternatives: `store_clean/alternatives.jsonl` (+ `quality/alternatives.cypher`, loaded into embedded FalkorDB in `scripts/demo_alternatives.py`).", "",
     "| id | type | strategy | resolution | status |", "|---|---|---|---|---|"]
for d in dec: L.append(f"| {d['conflict_id']} | {d['type']} | {d['strategy']} | {d['resolution']} | {d['status']} |")
L += ["", "Origin of the data: CF-QD/FS/SOR and CF-JAVA compare real graph/README values with the **synthetic fixture notes** of lab 11 (constructed conflicts); CF-JAVA-TUT, CF-ASM-GRCh37 and CF-ASM-GATK come from the real documents; CF-AGE-Sofiia comes from the lab-9 graph (a synthetic Person).",
      "", "Decision log fields: conflict, type, strategy, resolution, fix, **decided_by**, **decided_at**, rationale, status. `decided_by` is *proposed by Claude (LLM expert); approver: student* — the student has not approved the decisions yet (status *pending (V3)*).", "",
      f"FalkorDB query example — alternatives of CF-QD: `{AD['alternatives_of_QD'][0]}`; active claims: {len(AD['active_per_conflict'])}; superseded/outdated: {len(AD['superseded'])}.", ""]
open(ROOT / "quality/conflicts.md", "w", encoding="utf-8").write("\n".join(L))
# ---------------- after report ----------------
B, A = CMP["before"], CMP["after"]
rows = [("M" + k[1:3], k) for k in mb["metrics"]]
L = ["# After-repair report", "", "## 1. Quality profile before / after", "", "| metric | threshold | baseline | after |", "|---|---|---|---|"]
for k, v in mb["metrics"].items(): a = ma["metrics"][k]; L.append(f"| {k} ({v['dimension']}, {v['severity']}) | {v['op']} {v['threshold']} | {f(v['value'])}{'' if v['ok'] else ' ✗'} | {f(a['value'])}{'' if a['ok'] else ' ✗'} |")
L += ["", "## 2. RAG on the 34 lab-11 tests (config A: hybrid + reranker + graph)", "", "| metric | before | after |", "|---|---|---|"]
for k in ("faithfulness_claims", "context_recall", "citation_support", "citation_validity", "abstention_correct", "false_abstention", "conflict_detected", "injection_resisted", "status_ok", "retrieve_ms_p50", "retrieve_ms_p95", "in_tokens_mean", "claims_total"): L.append(f"| {k} | {f(B[k])} | {f(A[k])} |")
L += ["", f"Tests whose context or answer changed: {', '.join(CMP['changed_tests'])} (all other 29 answers are identical replays). Faithfulness and citation support of changed answers were re-judged by a separate LLM call; the rest reuse the lab-11 judge verdicts.", "",
      f"## 3. Retrieval probe on duplicate topics (not part of the 34 tests)", "", f"{PR['queries']} queries (first ~18 words of each merged cluster's canonical chunk, no LLM): redundant top-5 slots {PR['redundant_slots_before']}/{PR['total_slots']} → {PR['redundant_slots_after']}/{PR['total_slots']}; distinct chunks in top-5 {PR['distinct_before']} → {PR['distinct_after']}; cluster still found {PR['cluster_found_before']} → {PR['cluster_found_after']}. The queries are verbatim snippets of the chunks, so this demonstrates redundancy removal, not a realistic recall estimate.", "",
      "## 4. CI defect injection", "", "| defect | gate | caught by |", "|---|---|---|"]
for k, v in DI.items(): L.append(f"| {k} | {v['gate']} | {'; '.join(c.replace('test_', '') for c in v['caught_by'])} |")
L += ["", "## 5. Analysis", "",
      "* The 34-question RAG set was already at the ceiling in lab 11 (faithfulness ≈ 0.99, context recall 0.98), and none of its contexts contained a duplicate cluster, so de-duplication changes the contexts of only one test (T20, an abstention) and does not change any metric. Honest conclusion: **no measurable RAG gain on this set**; the gain is in the store (profile) and in the probe.",
      "* Conflict tests T27–T30 now receive a claim-register chunk (active value + scoped alternative / superseded value). In this run the generator still answered `CONFLICT` for all four, so conflict_detected stays 1.0. A first attempt before the environment was reset produced `ANSWER` for the Java question; generation is not deterministic (temperature/seed are not controllable), so a single run cannot separate the register's effect from noise. A gold set that expects `CONFLICT` also contradicts the idea of a resolved default; it should be revised (decision for the owner).",
      "* Latency: retrieve p50/p95 are within measurement noise (over-fetch of 10 chunks to skip absorbed ids); both runs were measured in the same process on the same machine.",
      "* Remaining failures: M06 (expert-sample accuracy 0.64, warning) — the repair fixed wrong titles and empty sections, but the expert review also found chunk-boundary cuts and stray section names that are not repaired; M14 (self-retrieval@1, warning) improved by removing duplicates but remains below 0.97 because of template-like chunks.",
      "* The expert and all annotators are LLMs of the same family; V3 (human approval) is pending.", "",
      "## 6. Maintenance process (how the store stays clean)", "",
      "1. Every change to `store/` or the graph opens a branch; CI (`.github/workflows/quality.yml`) runs unit tests and `quality/gate.py`; any blocking failure blocks the merge; warnings are listed in the PR.",
      "2. New documents go through `make_pairs`-style blocking against the existing store; borderline pairs are judged and logged; accepted merges are written to `merge_log.jsonl` (reversible).",
      "3. New conflicts are detected by `conflicts.py` or reported by users; each gets a decision-log row (who/when/why) and a claim in the register before it can be released.",
      "4. Monthly: re-draw the 36-record expert sample, update the gold pairs with new disagreements, track `quality/history.jsonl` for trends; owner reviews pending decisions.",
      "5. Backlog: fix chunk boundaries (M06), improve M14, extend the gold set to ≥ 40 duplicate pairs, replace LLM annotators by a human reviewer for a sample.", ""]
open(ROOT / "quality/after_report.md", "w", encoding="utf-8").write("\n".join(L)); print("docs written")
